$error=null;$success=null;$health=[];$compliance=[];$incidents=[];$counts=[];$csrf='';
try{$pdo=role_portal_db();role_portal_ensure($pdo);aia_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user){header('Location: ../login.php');exit;}if((string)($user['role_code']??'')!=='admin'){header('Location: access_denied.php');exit;}$orgId=pscms_org_id($pdo);$csrf=security_step17_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$id=(int)($_POST['incident_id']??0);$status=(string)($_POST['status']??'reviewing');$note=substr(trim((string)($_POST['resolution_note']??'')),0,2000);if(!in_array($status,['open','reviewing','resolved','dismissed'],true))throw new RuntimeException('Invalid incident status.');$s=$pdo->prepare("UPDATE public_ai_safety_incidents SET status=?,resolution_note=?,resolved_by=?,resolved_at=? WHERE id=? AND organization_id=?");$s->execute([$status,$note?:null,in_array($status,['resolved','dismissed'],true)?(int)$user['id']:null,in_array($status,['resolved','dismissed'],true)?date('Y-m-d H:i:s'):null,$id,$orgId]);security_step17_audit($pdo,(int)$user['id'],'ai_safety_incident_updated','public_ai_safety_incident',$id,['status'=>$status]);$success='Safety incident updated.';}$health=aia_training_health($pdo,$orgId);$compliance=aia_compliance($pdo,$orgId);foreach(['public_ai_unanswered'=>'unanswered','public_ai_knowledge_drafts'=>'drafts','public_ai_retraining_runs'=>'retraining_runs'] as $table=>$key){$s=$pdo->prepare("SELECT COUNT(*) FROM $table WHERE organization_id=?");$s->execute([$orgId]);$counts[$key]=(int)$s->fetchColumn();}$s=$pdo->prepare("SELECT * FROM public_ai_safety_incidents WHERE organization_id=? ORDER BY FIELD(status,'open','reviewing','resolved','dismissed'),created_at DESC LIMIT 100");$s->execute([$orgId]);$incidents=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
