$audit=['Verified public knowledge feed'=>true,'Crawler-friendly text feed'=>true,'JSON training export'=>true,'Plain-text training export'=>true,'Unanswered-question tracking'=>true,'Verified-only publishing workflow'=>true,'Topic-gap clustering'=>true,'Knowledge freshness monitoring'=>isset($health['checks']['freshness']),'Retraining fingerprint history'=>true,'Visitor safety incident reporting'=>true,'Open compliance flags'=>empty($compliance['flags']),'Open safety incidents'=>(int)($compliance['open_incidents']??0)===0];$passed=count(array_filter($audit));
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>AI Training Control Center</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>.ac-kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:14px 0}.ac-kpi,.ac-card{padding:16px;border:1px solid #dce7e0;border-radius:16px;background:#fff}.ac-kpi small,.ac-kpi b{display:block}.ac-kpi b{margin-top:5px;font-size:1.55rem}.ac-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.ac-check{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #e5ece8}.ac-state{padding:4px 8px;border-radius:999px;background:#eaf8ef;color:#176b42;font-size:.62rem;font-weight:850}.ac-state.bad{background:#fff0ed;color:#a33f31}.ac-flag,.ac-incident{margin-top:9px;padding:12px;border:1px solid #eadbd7;border-radius:12px;background:#fff8f6}.ac-form{display:grid;grid-template-columns:130px 1fr auto;gap:7px;margin-top:8px}.ac-form select,.ac-form input{border:1px solid #d8e3dc;border-radius:8px;padding:8px}.ac-form button,.ac-export{border:0;border-radius:9px;background:#167548;color:#fff;padding:9px 11px;font-weight:800;text-decoration:none}.ac-actions{display:flex;gap:8px;flex-wrap:wrap}.ac-muted{color:#687a70;font-size:.69rem}@media(max-width:950px){.ac-kpis{grid-template-columns:repeat(2,1fr)}.ac-grid{grid-template-columns:1fr}}@media(max-width:600px){.ac-kpis,.ac-form{grid-template-columns:1fr}}</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Final AI Training Control Center</small></span></a><div class="os-top-actions"><a class="os-btn" href="ai_training_health.php">Training Health</a><a class="os-btn" href="ai_quality_trends.php">Quality Trends</a><a class="os-btn primary" href="ai_knowledge_manager.php">Knowledge Manager</a></div></div></header><main class="os-main" style="max-width:1480px;margin:auto"><section class="os-hero"><div class="os-kicker">FINAL AI GOVERNANCE & TRAINING</div><h1>One control center for the complete AI lifecycle.</h1><p>Review safety, compliance, knowledge readiness, training exports, incidents and retraining evidence without exposing private Business OS data.</p><div class="os-status-row"><span class="os-chip <?=$passed===count($audit)?'good':''?>"><?=$passed?> / <?=count($audit)?> final checks ready</span><span class="os-chip"><?=(int)($health['score']??0)?>% training health</span><span class="os-chip"><?=(int)($compliance['score']??0)?>% compliance score</span></div></section><?php if($error):?><div class="pp-alert bad" style="margin-top:14px"><?=acc_h($error)?></div><?php endif;?><?php if($success):?><div class="pp-alert good" style="margin-top:14px"><?=acc_h($success)?></div><?php endif;?><section class="ac-kpis"><article class="ac-kpi"><small>Verified Answers</small><b><?=(int)($health['verified_answers']??0)?></b></article><article class="ac-kpi"><small>Unanswered Records</small><b><?=(int)($counts['unanswered']??0)?></b></article><article class="ac-kpi"><small>Knowledge Drafts</small><b><?=(int)($counts['drafts']??0)?></b></article><article class="ac-kpi"><small>Retraining Records</small><b><?=(int)($counts['retraining_runs']??0)?></b></article><article class="ac-kpi"><small>Open Incidents</small><b><?=(int)($compliance['open_incidents']??0)?></b></article></section><section class="ac-grid"><article class="ac-card"><h2>Final AI Audit</h2><?php foreach($audit as $name=>$ok):?><div class="ac-check"><span><?=acc_h($name)?></span><span class="ac-state <?=$ok?'':'bad'?>"><?=$ok?'READY':'ACTION NEEDED'?></span></div><?php endforeach;?><h2 style="margin-top:18px">Training Pack</h2><p class="ac-muted">Exports contain only public-site content, services, verified answers and safety policies.</p><div class="ac-actions"><a class="ac-export" href="ai_training_export.php?format=json">Download JSON</a><a class="ac-export" href="ai_training_export.php?format=text">Download Text</a><a class="ac-export" href="../public_ai_knowledge.php?format=text" target="_blank">Preview Crawler Feed</a></div></article><article class="ac-card"><h2>Compliance Scan</h2><p class="ac-muted">Duplicate questions and risky wording are flagged for human review; nothing is automatically deleted.</p><?php if(empty($compliance['flags'])):?><div class="ac-check"><span>No duplicate or risky verified-answer wording detected.</span><span class="ac-state">PASS</span></div><?php endif;?><?php foreach($compliance['flags']??[] as $f):?><div class="ac-flag"><b><?=acc_h(strtoupper((string)$f['type']))?></b><div class="ac-muted"><?=acc_h((string)$f['text'])?></div><a href="ai_knowledge_manager.php">Review verified answer →</a></div><?php endforeach;?></article><article class="ac-card" style="grid-column:1/-1"><h2>Risky / Inaccurate Answer Incidents</h2><p class="ac-muted">Visitors can report unsafe or inaccurate answers from the public AI panel. Reports require admin review.</p><?php if(!$incidents):?><p class="ac-muted">No safety incidents recorded.</p><?php endif;?><?php foreach($incidents as $r):?><div class="ac-incident"><b><?=acc_h((string)$r['report_text'])?></b><div class="ac-muted"><?=acc_h((string)($r['page_path']?:'Unknown page'))?> • <?=acc_h((string)$r['created_at'])?> • <?=acc_h(strtoupper((string)$r['status']))?></div><form method="post" class="ac-form"><input type="hidden" name="csrf" value="<?=acc_h($csrf)?>"><input type="hidden" name="incident_id" value="<?=(int)$r['id']?>"><select name="status"><?php foreach(['open'=>'Open','reviewing'=>'Reviewing','resolved'=>'Resolved','dismissed'=>'Dismissed'] as $v=>$label):?><option value="<?=$v?>" <?=$r['status']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select><input name="resolution_note" maxlength="2000" placeholder="Review or resolution note" value="<?=acc_h((string)($r['resolution_note']??''))?>"><button>Update</button></form></div><?php endforeach;?></article></section><div class="os-footer-note"><strong>Training boundary:</strong> this system prepares, validates, exports and records the training lifecycle. Chatbase retraining itself must be completed against the online HTTPS crawler feed, then recorded in AI Training Health.</div></main></body></html>
